import * as T from './three.module.js';
import {load} from './core.js';export {T};
export function engine({sky=0x91cbd2,fog=180,shadows=true}={}){const host=document.querySelector('#world');let renderer;try{renderer=new T.WebGLRenderer({antialias:true,powerPreference:'high-performance'})}catch{host.innerHTML='<div class="loading">WebGL is unavailable. Try reopening in Safari.</div>';throw Error('WebGL unavailable')};renderer.setPixelRatio(Math.min(devicePixelRatio,load('quality','balanced')==='high'?2:1.5));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=shadows;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;renderer.domElement.className='scene';host.append(renderer.domElement);const scene=new T.Scene();scene.background=new T.Color(sky);if(sky>0x500000){const c=document.createElement('canvas');c.width=4;c.height=256;const ctx=c.getContext('2d'),grad=ctx.createLinearGradient(0,0,0,256);grad.addColorStop(0,'#4d90b2');grad.addColorStop(.55,'#b8d7db');grad.addColorStop(1,'#e6dec1');ctx.fillStyle=grad;ctx.fillRect(0,0,4,256);scene.background=new T.CanvasTexture(c);scene.background.colorSpace=T.SRGBColorSpace;}scene.fog=new T.Fog(sky,fog*.4,fog);const camera=new T.PerspectiveCamera(52,innerWidth/innerHeight,.1,600);scene.add(new T.HemisphereLight(0xc8e5f4,0x2c433b,2.3));const sun=new T.DirectionalLight(0xffe0b1,3);sun.position.set(-35,65,25);sun.castShadow=shadows;sun.shadow.mapSize.set(1024,1024);Object.assign(sun.shadow.camera,{left:-70,right:70,top:70,bottom:-70,near:1,far:180});sun.shadow.bias=-.001;scene.add(sun);const resize=()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)};addEventListener('resize',resize);let frame,previous=performance.now();return {scene,camera,renderer,sun,start(fn){const loop=t=>{frame=requestAnimationFrame(loop);const dt=Math.min((t-previous)/1000,.04);previous=t;fn(dt,t/1000);renderer.render(scene,camera)};frame=requestAnimationFrame(loop)},dispose(){cancelAnimationFrame(frame);removeEventListener('resize',resize);scene.traverse(o=>{o.geometry?.dispose();if(o.material){for(const m of Array.isArray(o.material)?o.material:[o.material]){m.map?.dispose();m.dispose()}}});scene.background?.dispose?.();renderer.dispose();renderer.domElement.remove()}}}
const materials=new Map();export function material(color,rough=.8,metal=0){const key=color+':'+rough+':'+metal;if(!materials.has(key))materials.set(key,new T.MeshStandardMaterial({color,roughness:rough,metalness:metal}));return materials.get(key).clone()}
export function box(scene,x,y,z,w,h,d,color,rough=.8){const m=new T.Mesh(new T.BoxGeometry(w,h,d),material(color,rough));m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;scene.add(m);return m}
export function sphere(scene,x,y,z,r,color,sx=1,sy=1,sz=1){const m=new T.Mesh(new T.SphereGeometry(r,20,14),material(color,.55));m.position.set(x,y,z);m.scale.set(sx,sy,sz);m.castShadow=true;m.receiveShadow=true;scene.add(m);return m}
export function cylinder(scene,x,y,z,rt,rb,h,color,n=16){const m=new T.Mesh(new T.CylinderGeometry(rt,rb,h,n),material(color));m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;scene.add(m);return m}
export function ground(scene,color=0x477448,size=500){return box(scene,0,-.35,0,size,.6,size,color)}
let foliageTexture;
export function tree(scene,x,z,scale=1,pine=false){foliageTexture??=new T.TextureLoader().load(new URL('../assets/coastal-pine.webp',import.meta.url).href);foliageTexture.colorSpace=T.SRGBColorSpace;const g=new T.Group();for(let i=0;i<2;i++){const mat=new T.MeshStandardMaterial({map:foliageTexture,alphaTest:.45,side:T.DoubleSide,roughness:1,color:0xe1eddb});const m=new T.Mesh(new T.PlaneGeometry(9,8.2),mat);m.position.y=4.1;m.rotation.y=i*Math.PI/2;m.castShadow=true;m.receiveShadow=true;g.add(m)}g.position.set(x,0,z);g.rotation.y=(x+z)*.17;g.scale.setScalar(scale);scene.add(g);return g}
export function line(scene,points,color=0xffffff){const geo=new T.BufferGeometry().setFromPoints(points.map(p=>new T.Vector3(...p)));const l=new T.Line(geo,new T.LineBasicMaterial({color}));scene.add(l);return l}
export function label(scene,text,x,y,z,{color='#ffffff',size=6}={}){const c=document.createElement('canvas');c.width=512;c.height=128;const a=c.getContext('2d');a.fillStyle='rgba(5,20,25,.82)';a.roundRect(0,0,512,128,20);a.fill();a.fillStyle=color;a.font='600 48px system-ui';a.textAlign='center';a.textBaseline='middle';a.fillText(text,256,64);const tex=new T.CanvasTexture(c);tex.colorSpace=T.SRGBColorSpace;const sp=new T.Sprite(new T.SpriteMaterial({map:tex,depthTest:false}));sp.position.set(x,y,z);sp.scale.set(size,size/4,1);scene.add(sp);return sp}
export function water(scene,x,z,w,d){const m=new T.Mesh(new T.PlaneGeometry(w,d,30,30),new T.MeshStandardMaterial({color:0x168a9b,roughness:.2,metalness:.45,transparent:true,opacity:.88}));m.rotation.x=-Math.PI/2;m.position.set(x,-.05,z);m.userData.dynamic=true;scene.add(m);const base=m.geometry.attributes.position.array.slice();return {mesh:m,update(t){const a=m.geometry.attributes.position;for(let i=0;i<a.count;i++)a.setZ(i,Math.sin(base[i*3]*.17+t*.8)*.09+Math.cos(base[i*3+1]*.2+t)*.06);a.needsUpdate=true;m.geometry.computeVertexNormals()}}}
// Combine static scenery by material to keep mobile draw-call counts bounded.
export function batchStatic(scene){scene.updateMatrixWorld(true);const groups=new Map();scene.traverse(o=>{if(!o.isMesh||o.userData.dynamic||Array.isArray(o.material)||o.material.map)return;const m=o.material,key=[m.type,m.color?.getHex(),m.emissive?.getHex(),m.emissiveIntensity,m.roughness,m.metalness,m.opacity,m.transparent,m.side,o.castShadow,o.receiveShadow].join(':');if(!groups.has(key))groups.set(key,[]);groups.get(key).push(o)});for(const list of groups.values()){if(list.length<3)continue;const positions=[],normals=[],uvs=[];for(const o of list){let g=o.geometry.index?o.geometry.toNonIndexed():o.geometry.clone();g.applyMatrix4(o.matrixWorld);positions.push(...g.attributes.position.array);if(g.attributes.normal)normals.push(...g.attributes.normal.array);if(g.attributes.uv)uvs.push(...g.attributes.uv.array);g.dispose()}const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(positions,3));if(normals.length===positions.length)g.setAttribute('normal',new T.Float32BufferAttribute(normals,3));else g.computeVertexNormals();if(uvs.length===positions.length/3*2)g.setAttribute('uv',new T.Float32BufferAttribute(uvs,2));g.computeBoundingSphere();const m=new T.Mesh(g,list[0].material.clone());m.castShadow=list[0].castShadow;m.receiveShadow=list[0].receiveShadow;for(const o of list){o.parent.remove(o);o.geometry.dispose();o.material.dispose()}scene.add(m)}}
